import { createActor, createMachine } from 'xstate'

const fetcher = createMachine({
  id: 'fetcher',
  initial: 'idle',
  states: {
    idle: { on: { FETCH: 'loading' } },
    loading: { on: { SUCCESS: 'done', ERROR: 'error' } },
    error: { on: { RETRY: 'loading' } },
    done: { type: 'final' },
  },
})

const actor = createActor(fetcher).start()
actor.subscribe((snapshot) => console.log(snapshot.value))

actor.send({ type: 'FETCH' }) // 'loading'
actor.send({ type: 'FETCH' }) // not handled in 'loading': stays 'loading'
