import { createMachine } from '@pyreon/machine'
import { signal } from '@pyreon/reactivity'

const cart = signal<string[]>([])
const user = signal<string | null>(null)

const checkout = createMachine({
  initial: 'validating',
  states: {
    // routes itself the moment it is entered
    validating: {
      always: [
        { target: 'empty', guard: () => cart().length === 0 },
        { target: 'needsLogin', guard: () => !user() },
        'ready',
      ],
    },
    empty: { on: { ADD: 'validating' } },
    needsLogin: { on: { LOGIN: 'validating' } },
    ready: { on: { PAY: { target: 'paying', guard: (p) => (p as { total: number }).total > 0 } } },
    paying: { on: { PAID: 'done', DECLINED: 'ready' } },
    done: { final: true },
  },
})

checkout.onTransition((from, to, event) => console.log(`${from} → ${to} (${event.type})`))

cart.set(['book'])
checkout.send('ADD') // settles in 'needsLogin', after passing through 'validating'
user.set('ada')
checkout.send('LOGIN') // 'ready'
console.log(checkout.nextEvents(), checkout.can('PAY', { total: 42 })) // ['PAY'] true
checkout.send('PAY', { total: 0 }) // guard says no: still 'ready'
checkout.send('PAY', { total: 42 }) // 'paying'
